class Solution {
public:
    int maxValueAfterReverse(vector<int>& nums) {
        int n = nums.size();
        long long base = 0;
        for (int i = 0; i + 1 < n; ++i)
            base += abs(nums[i + 1] - nums[i]);

        long long best = 0;

        // Boundary reversals: prefix [0..i] and suffix [i+1..n-1]
        for (int i = 0; i + 1 < n; ++i) {
            long long d = abs(nums[i] - nums[i + 1]);
            best = max(best, (long long)abs(nums[0] - nums[i + 1]) - d);
            best = max(best, (long long)abs(nums[n - 1] - nums[i]) - d);
        }

        // Interior reversals via 4 sign cases.
        // left[s][t] = max over i of (s*a[i] + t*a[i+1] - d[i]), s,t in {-1,+1}
        long long left[2][2];
        const long long NEG = LLONG_MIN / 4;
        for (int s = 0; s < 2; ++s)
            for (int t = 0; t < 2; ++t)
                left[s][t] = NEG;

        for (int j = 0; j + 1 < n; ++j) {
            long long x = nums[j], y = nums[j + 1];
            long long d = abs(y - x);
            // update left table with pair (x, y) as the (L-1, L) pair
            for (int s = 0; s < 2; ++s) {
                long long sx = s ? x : -x;
                for (int t = 0; t < 2; ++t) {
                    long long ty = t ? y : -y;
                    left[s][t] = max(left[s][t], sx + ty - d);
                }
            }
            // use pair (x, y) as the (R, R+1) pair: contribution -s*x - t*y - d
            for (int s = 0; s < 2; ++s) {
                long long sx = s ? x : -x;
                for (int t = 0; t < 2; ++t) {
                    long long ty = t ? y : -y;
                    if (left[s][t] != NEG)
                        best = max(best, left[s][t] - sx - ty - d);
                }
            }
        }

        return (int)(base + best);
    }
};
